    nvgStrokeWidth(vg, 5)
    nvgBeginPath(vg)
    nvgMoveTo(vg, x, y)
    nvgLineTo(vg, x, y - 56)
    nvgStroke(vg)
    nvgBeginPath(vg)
    nvgMoveTo(vg, x, y - 56)
    nvgBezierTo(vg, x + 16, y - 62, x + 22, y - 50, x + 25, y - 42)
    nvgStrokeWidth(vg, 3.5)
    nvgStroke(vg)
