-- 描摹层渲染(1:1):各层按视差对齐参考相机位
local function drawTraceLayers()
    local TR_REFX, TR_REFY = LV.REFX or 840, LV.REFY or 455
    local zoom = LV.ZOOM or CAM_ZOOM
    local halfW = (screenW / 2) / zoom + 60
    local halfH = (screenH / 2) / zoom + 60
    for _, L in ipairs(LV.TRACE.layers) do
        local tox = (camX - TR_REFX) * (1 - L.par)
        local toy = (camY - TR_REFY) * (1 - L.par) * 0.5
        nvgSave(vg)
        nvgTranslate(vg, tox, toy)
        nvgFillColor(vg, rgba(L.color[1], L.color[2], L.color[3], 255))
        local vx1, vx2 = camX - halfW - tox, camX + halfW - tox
        local vy1, vy2 = camY - halfH - toy, camY + halfH - toy
        for pi, poly in ipairs(L.polys) do
            local bb = L.bb and L.bb[pi]
            if (not bb) or (bb[3] > vx1 and bb[1] < vx2 and bb[4] > vy1 and bb[2] < vy2) then
                nvgBeginPath(vg)
                nvgMoveTo(vg, poly[1], poly[2])
                for k = 3, #poly - 1, 2 do nvgLineTo(vg, poly[k], poly[k + 1]) end
                nvgClosePath(vg)
                nvgFill(vg)
            end
        end
        nvgRestore(vg)
    end
end

-- ============================================================================
-- 渲染:前景地形 + 边缘样式
-- ============================================================================
local function drawTerrain()
    local PAL = LV.PAL
    for pi, poly in ipairs(LV.POLYS) do
        local isTable = LV.TABLES and LV.TABLES[pi]
        nvgBeginPath(vg)
        nvgMoveTo(vg, poly[1][1], poly[1][2])
        for i = 2, #poly do nvgLineTo(vg, poly[i][1], poly[i][2]) end
        nvgClosePath(vg)
        nvgFillColor(vg, col(PAL.fore))
        nvgFill(vg)

        local x1, y1 = poly[1][1], poly[1][2]
        local x2, y2 = poly[2][1], poly[2][2]
        if isTable then
            -- 白顶石台
            nvgStrokeColor(vg, rgba(244, 240, 226, 250))
            nvgStrokeWidth(vg, 7)
            nvgBeginPath(vg)
            nvgMoveTo(vg, x1, y1 + 2)
            nvgLineTo(vg, x2, y2 + 2)
            nvgStroke(vg)
        elseif PAL.trim == "grass" then
            -- 草缘(神庙)
            nvgFillColor(vg, col(PAL.fore))
            for gx = x1 + 6, x2 - 6, 24 do
                if hash01(gx * 0.7) > 0.25 then
                    local gh = 5 + hash01(gx) * 8
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, gx, y1 + 1)
                    nvgBezierTo(vg, gx + 2, y1 - gh * 0.7, gx + 3 + hash01(gx + 1) * 3, y1 - gh, gx + 5 + hash01(gx + 2) * 3, y1 - gh * 0.5)
                    nvgLineTo(vg, gx + 7, y1 + 1)
                    nvgClosePath(vg)
                    nvgFill(vg)
                end
            end
        elseif PAL.trim == "gold" then
            -- 金色灯带镶边(森林:全部外缘)
            local n = #poly
            for i = 1, n do
                local ax, ay = poly[i][1], poly[i][2]
                local bx, by = poly[i % n + 1][1], poly[i % n + 1][2]
                nvgStrokeColor(vg, col(PAL.acc, 230))
                nvgStrokeWidth(vg, 3.5)
                nvgBeginPath(vg)
                nvgMoveTo(vg, ax, ay)
                nvgLineTo(vg, bx, by)
                nvgStroke(vg)
                -- 灯带珠点
                local segLen = math.sqrt((bx - ax) ^ 2 + (by - ay) ^ 2)
                local nb = math.floor(segLen / 60)
                for k = 0, nb do
                    local t = (k + 0.5) / (nb + 1)
                    local px2 = ax + (bx - ax) * t
                    local py2 = ay + (by - ay) * t
                    nvgBeginPath(vg)
                    nvgCircle(vg, px2, py2, 2.6 + math.sin(elapsed * 3 + k + pi) * 0.8)
                    nvgFillColor(vg, col(PAL.acc, 240))
                    nvgFill(vg)
                end
            end
        elseif PAL.trim == "mauve" then
            if #poly == 4 then
                nvgFillColor(vg, col(PAL.foreDk, 160))
                nvgBeginPath(vg)
                nvgRect(vg, poly[2][1] - 30, poly[2][2], 30, poly[3][2] - poly[2][2])
                nvgFill(vg)
            end
            -- 紫废墟:顶缘暗影线 + 着力点金线
            nvgStrokeColor(vg, col(PAL.foreDk, 230))
            nvgStrokeWidth(vg, 6)
            nvgBeginPath(vg)
            nvgMoveTo(vg, x1, y1 + 4)
            nvgLineTo(vg, x2, y2 + 4)
            nvgStroke(vg)
            nvgStrokeColor(vg, col(PAL.acc, 170))
            nvgStrokeWidth(vg, 2.6)
            nvgBeginPath(vg)
            nvgMoveTo(vg, x1 + 8, y1)
            nvgLineTo(vg, math.min(x1 + 150, x2 - 8), y1)
            nvgStroke(vg)
        elseif PAL.trim == "wdash" then
            -- 水城:白点饰边
            local segLen = x2 - x1
            nvgFillColor(vg, rgba(255, 255, 255, 185))
            for k = 0, math.floor(segLen / 20) do
                nvgBeginPath(vg)
                nvgRect(vg, x1 + k * 20 + 6, y1 - 2.5, 9, 3.5)
                nvgFill(vg)
            end
        elseif PAL.trim == "blue" then
            nvgStrokeColor(vg, col(PAL.acc, 200))
            nvgStrokeWidth(vg, 3.4)
            nvgBeginPath(vg)
            nvgMoveTo(vg, x1 + 3, y1 + 2)
            nvgLineTo(vg, x2 - 3, y2 + 2)
            nvgStroke(vg)
        end
    end
end

